 * Ready-made programs (public templates). Safe to re-run.
 *
 * Two shapes:
 *  - 'days'  → one week is described and 8 weeks are generated from it, in two 4-week blocks:
 *              block 2 lowers reps on main lifts and pushes effort ~1 RPE higher.
 *  - 'weeks' → every week is written out: [block, [[title_en, title_ru, [rows]], ...]].
 *              'notes' holds the default notes_en per exercise; a row can override it.
 */
