        'push-pull-legs-hypertrophy' => [
            'name_en' => 'Push/Pull/Legs Hypertrophy',
            'name_ru' => 'Жим/Тяга/Ноги: гипертрофия',
            'description_en' => '6 days a week, 16 weeks, for experienced lifters focused on muscle size. Push/Pull/Legs run twice a week with supersets, tempo and paused reps; main lifts use % of 1RM. Two 8-week blocks; the second one starts with a lighter week. High volume — make sure you can recover from 6 sessions a week.',
            'description_ru' => '6 дней в неделю, 16 недель, для опытных, цель — мышечная масса. Жим/Тяга/Ноги дважды в неделю, суперсеты, темповые повторы и паузы; базовые упражнения — в % от 1ПМ. Два блока по 8 недель, второй начинается с облегчённой недели. Большой объём — убедись, что восстанавливаешься при 6 тренировках в неделю.',
            'notes' => [
                '1-arm-lat-pull-in' => 'Light sets, drive your elbow down and in toward your side',
                'ab-wheel-rollout' => 'Keep your pelvis posteriorly tilted (squeeze your glutes), cut the ROM short if you can\'t maintain this position',
                'arnold-press' => 'Start your shoulders internally rotated, gradually externally rotate',
                'back-squat' => 'Sit back and down, 15° toe flare, drive your knees out laterally',
                'barbell-bench-press' => 'Tuck elbows at a 45° angle, keep your scapulae retracted and depressed',
                'barbell-floor-skull-crusher' => 'Protract your shoulders, keep your elbows in line with your head',
                'barbell-hip-thrust' => 'Tuck your chin and rib cage down, only move your hips. Use a pad',
                'bicycle-crunch' => 'Opposite knee to elbow, focus on flexing your spine',
                'cable-lateral-raise' => 'Focus on squeezing your lateral delt to move the weight',
                'cable-pull-over' => 'Kneeling, straight arms. Lean your torso at a 45° angle, focus on pulling the weight straight down, not "in"',
                'cable-pull-through' => 'Focus on anteriorly tilting your pelvis during the eccentric, posteriorly during the concentric',
                'cable-reverse-flye' => 'Focus on sweeping the weight out laterally',
                'cable-seated-elbows-out-row' => 'Superset a1. Focus on scapular retraction, pull with your elbows up and out',
                'cable-seated-row' => 'Superset a2. Focus on scapular retraction, pull with your elbows down and in',
                'cable-tricep-kickback' => 'Stand upright, keep your elbows behind your torso',
                'cable-upright-row' => 'Rope. Focus on squeezing the upper traps at the top',
                'chest-supported-t-bar-row' => null,
                'close-grip-bench-press' => 'Shoulder width grip, elbows down at your sides',
                'close-grip-smith-machine-press' => 'Shoulder width grip, elbows down at your sides',
                'deadlift' => 'Brace your lats, chest tall, hips high, pull the slack out of the bar prior to moving it off the ground',
                'dip' => 'Slow eccentric. 3-second lowering phase. Tuck elbows at a 45° angle, lean your torso forward 15°',
                'dumbbell-incline-press' => 'Keep your scapulae retracted and depressed',
                'dumbbell-lateral-raise' => 'Tilt the dumbbell such that your pinky comes up first',
                'dumbbell-preacher-curl' => 'Focus on squeezing your biceps to move the weight',
                'dumbbell-pronated-curl' => 'Superset a1. Arch the dumbbell "out", not "up". Focus on squeezing your forearms',
                'dumbbell-row' => 'Brace with your non-working arm, pull your arms back at your sides',
                'dumbbell-seated-shoulder-press' => 'Bring the dumbbell all the way down, keep your torso upright on the bench',
                'dumbbell-skull-crusher' => 'One arm at a time. Keep your elbow fixed in line with the top of your head, press the dumbbell over your head (not in front of your face)',
                'dumbbell-supinated-curl' => 'Superset a3. Arch the dumbbell "out", not "up". Focus on squeezing your biceps',
                'dumbbell-walking-lunge' => 'Take medium strides, minimize the amount you push off your rear leg',
                'egyptian-lateral-raise' => 'Lean away from the cable, focus on squeezing your delts',
                'ez-bar-curl' => 'Superset a2. Arch the bar "out", not "up". Focus on squeezing your biceps',
                'front-squat' => 'Sit down, 15° toe flare, drive your knees out laterally',
                'goblet-squat' => 'Slow eccentric. 3-second lowering phase. Sit down, knees out, torso upright',
                'hammer-curl' => 'Focus on squeezing your biceps to move the weight',
                'hanging-leg-raise' => 'Focus on flexing your spine',
                'lateral-band-walk' => 'Or machine hip abduction, focus on driving your knees out',
                'leg-extension' => 'Superset a1. Focus on squeezing your quads to move the weight',
                'low-to-high-cable-flye' => 'Start externally rotated with your elbows down and out, pull your elbows (not hands) up and in while slightly internally rotating your shoulder',
                'lying-leg-curl' => 'Enhanced eccentric. Have a training partner push down on the pad during the eccentric',
                'machine-high-row' => 'Focus on squeezing your lats',
                'machine-lateral-raise' => 'Focus on squeezing your lateral delt to move the weight',
                'military-press' => 'Squeeze your glutes to keep your torso upright, clear your head out of the way, press up and slightly back',
                'neutral-grip-pulldown' => 'Pull your elbows down against your sides',
                'pec-deck' => 'Focus on bringing your inner elbows together - not your hands',
                'pendlay-row' => 'Initiate the movement with scapular retraction, pull to your lower chest, keep your torso motionless',
                'plank' => 'Keep your pelvis posteriorly tilted',
                'pull-up' => 'Pull your elbows down and in, minimize swinging',
                'reverse-grip-ez-bar-curl' => 'Superset a1. Arch the bar "out", not "up". Focus on squeezing your forearms',
                'reverse-pec-deck' => 'Sweep your arms out laterally, keep your scapulae protracted',
                'romanian-deadlift' => 'Keep your spine neutral, tilt your pelvis forward (anterior tilt) during the lowering phase',
                'rope-overhead-triceps-extension' => 'Focus on stretching your triceps at the bottom of the movement',
                'round-back-hyperextension' => 'With a dumbbell. Upper back rounded, drive your hips into the pad like a hip thrust',
                'seal-row' => 'You can do this with dumbbells or a barbell',
                'seated-face-pull' => 'Pull your elbows up and out, retract your scapulae',
                'seated-leg-curl' => 'Superset a2. Focus on squeezing your hamstrings to move the weight',
                'single-arm-cable-curl' => 'Stand upright, keep your elbow behind your torso',
                'single-arm-pulldown' => 'Start with your weaker side, stretch your lat at the top, pull down and in',
                'single-leg-leg-extension' => 'Start with your weaker leg, focus on squeezing your quads to move the weight',
                'single-leg-leg-press' => 'High foot placement',
                'smith-machine-reverse-lunge' => 'Sit back, start with your weaker leg',
                'snatch-grip-barbell-shrug' => 'Use a 1.5x shoulder width grip, control the weight and shrug up to your ears',
                'spider-curl' => 'Brace your chest against an incline bench, curl with your elbows slightly in front of you',
                'standing-calf-raise' => 'Press all the way up to your toes, stretch your calves at the bottom, don\'t bounce',
                'swiss-ball-leg-curl' => 'Single leg. Start with your weaker leg, keep your hips off the ground',
                'v-bar-pressdown' => 'Focus on squeezing your triceps to move the weight',
                'weighted-dip' => 'Tuck your elbows at a 45° angle, lean your torso forward 15°, keep your scapulae retracted',
            ],
