        'upper-lower-strength-size' => [
            'name_en' => 'Upper/Lower Strength & Size',
            'name_ru' => 'Верх/Низ: сила и масса',
            'description_en' => '6 days a week, 9 weeks, for experienced lifters who want both strength and size. Upper/lower split three times a week; main lifts follow % of 1RM in three 3-week waves, with AMRAP sets to gauge progress. Accessories use supersets, drop sets and myo-reps.',
            'description_ru' => '6 дней в неделю, 9 недель, для опытных, цель — и сила, и масса. Верх/низ трижды в неделю; базовые упражнения идут по % от 1ПМ тремя волнами по 3 недели, подходы AMRAP показывают прогресс. В подсобке — суперсеты, дроп-сеты и майо-повторы.',
            'notes' => [
                'arnold-press' => 'Externally rotate while you press',
                'back-extension' => 'With a barbell. Keep your spine neutral',
                'back-squat' => 'Sit back and down, 15° toe flare, drive your knees out laterally',
                'band-pull-apart' => 'Pull via shoulder extension',
                'barbell-bench-press' => 'Elbows at a 45° angle. Keep your scapulae retracted and depressed',
                'barbell-bent-over-row' => 'Pull to your upper abs',
                'barbell-floor-press' => 'Focus on squeezing your chest',
                'barbell-floor-skull-crusher' => 'Myo-reps. Focus on squeezing your triceps',
                'barbell-hip-thrust' => 'Fully extend your hips',
                'barbell-incline-press' => 'Keep your elbows out',
                'barbell-push-press' => 'Control the negative',
                'barbell-supinated-row' => 'Pull via shoulder extension',
                'bulgarian-split-squat' => 'Elevate your back foot ~30 cm (12")',
                'cable-close-grip-row' => 'Pull via shoulder extension',
                'cable-crunch' => 'Round your back as you crunch',
                'cable-flye' => '21s. 7 reps top half of ROM, 7 reps bottom half of ROM, 7 reps full ROM',
                'cable-pull-through' => 'Superset a2. Focus on squeezing your glutes',
                'cable-seated-row' => 'Eccentric-accentuated. 2-second lowering phase',
                'cable-tricep-kickback' => 'Focus on squeezing your triceps',
                'cable-upright-row' => null,
                'california-press' => 'Lower like a skull crusher, press up like a close-grip bench press',
                'chest-supported-machine-row' => 'Band-resisted. Focus on protraction/retraction',
                'chest-supported-t-bar-row' => 'Band-resisted. Focus on scapular retraction',
                'close-grip-bench-press' => 'Shoulder width grip',
                'deadlift' => 'Brace your lats, chest tall, hips high, pull the slack out of the bar',
                'deficit-deadlift' => '5 cm (2") deficit — stand on a plate or a low platform',
                'dip' => 'Keep your scapulae retracted and depressed',
                'dumbbell-front-lateral-raise' => '15 reps front raise, 15 reps lateral raise',
                'dumbbell-incline-press' => 'Pause at the bottom. 3-second pause',
                'dumbbell-row' => 'Pull via shoulder extension',
                'dumbbell-step-up' => 'Set the box to ~parallel',
                'dumbbell-supinated-curl' => 'Supinate against the dumbbell',
                'dumbbell-walking-lunge' => '15 steps per leg',
                'ez-bar-curl' => '21s. 7 reps bottom half of ROM, 7 reps top half of ROM, 7 reps full ROM',
                'front-squat' => 'Keep your torso upright',
                'good-morning' => 'Keep your spine neutral',
                'hammer-curl' => 'Eccentric-accentuated. 3-second lowering phase',
                'hanging-leg-raise' => 'Round your back as you crunch',
                'lat-pulldown' => 'Pull your elbows down and in',
                'leg-curl' => 'Superset a2. Flex your hamstrings',
                'leg-extension' => 'Superset a2. Focus on squeezing your quads',
                'leg-press' => 'Constant tension. Don\'t stop in between reps',
                'lying-leg-curl' => 'Constant tension. Flex your hamstrings',
                'machine-chest-press' => 'Focus on squeezing your chest',
                'machine-high-row' => 'Stretch your lats at the top',
                'machine-lateral-raise' => 'Dropset',
                'machine-seated-hip-abduction' => 'Squeeze your glutes',
                'machine-shoulder-press' => 'Constant tension. Don\'t stop in between reps',
                'military-press' => 'Squeeze your glutes to keep your torso upright',
                'neutral-grip-pull-up' => 'AMRAP at RPE 8, then do 2 forced negatives',
                'pec-deck' => 'Squeeze your pecs',
