        'womens-foundations-4-day-upper-lower' => [
            'name_en' => 'Women\'s Foundations · 4-Day Upper/Lower',
            'name_ru' => 'Женская базовая программа · 4 дня, верх/низ',
            'description_en' => '4 days a week, 8 weeks. Two lower-body days built around glutes and legs plus two upper-body days for a balanced, toned physique. Warm-up sets before the main lifts, moderate effort (RPE 6–9), two 4-week blocks.',
            'description_ru' => '4 дня в неделю, 8 недель. Два дня на низ с акцентом на ягодицы и ноги и два дня на верх — для гармоничной, подтянутой фигуры. Разминочные подходы перед основными упражнениями, умеренное усилие (RPE 6–9), два блока по 4 недели.',
            'notes' => [
                'assisted-pull-up' => 'Pull your elbows down towards your waist',
                'back-squat' => 'Sit down and back, keep your knees out',
                'barbell-curl' => 'Focus on squeezing your biceps',
                'barbell-hip-thrust' => 'Keep your rib cage and chin tucked',
                'bicycle-crunch' => 'Focus on flexing and rotating your spine',
                'cable-glute-kickback' => 'Focus on squeezing your glutes to move the weight',
                'cable-pull-through' => 'Focus on extending your hips',
                'cable-seated-row' => 'Pull your elbows down at your sides',
                'cable-tricep-kickback' => 'Rope. Keep your elbow behind your torso',
                'cable-upright-row' => 'Pull until your upper arms are parallel to the ground',
                'chest-supported-machine-row' => 'Pull your elbows up and out, squeeze your shoulder blades together',
                'crunch' => 'Flex your spine - don\'t yank your head',
                'deadlift' => 'Keep your hips high, lumbar spine neutral',
                'donkey-kickback' => 'Focus on squeezing your glutes',
                'dumbbell-alternating-curl' => 'Focus on squeezing your biceps',
                'dumbbell-bench-press' => 'Keep your shoulder blades back and down',
                'dumbbell-front-raise' => 'Focus on squeezing your front delts',
                'dumbbell-lateral-raise' => 'Slightly internally rotate your shoulder',
                'dumbbell-row' => 'Pull your elbow down and back toward your hip',
                'dumbbell-seated-shoulder-press' => 'Keep your torso upright',
                'dumbbell-walking-lunge' => '15 steps each leg. Keep your front shin vertical',
                'hanging-leg-raise' => 'Squeeze your glutes',
                'isolateral-pulldown' => 'Pull your elbows down and in',
                'lat-pulldown' => 'Pull your elbows down and in',
                'lying-leg-curl' => 'Squeeze your hamstrings',
                'machine-chest-press' => 'Keep your shoulder blades back and down',
                'machine-seated-hip-abduction' => 'Flex your glutes',
                'military-press' => 'Squeeze your glutes to keep your torso upright',
                'plank' => 'Squeeze your glutes, flex your spine',
                'preacher-curl' => 'Squeeze your biceps',
                'reverse-pec-deck' => 'Swing the weight out to the sides',
                'rope-overhead-triceps-extension' => 'Focus on squeezing your triceps',
                'rope-triceps-pressdown' => 'Squeeze your triceps',
                'round-back-hyperextension' => 'Round your back, drive your hips into the pad like a hip thrust',
                'seated-calf-raise' => 'Press up onto your toes',
                'seated-face-pull' => 'Pull your elbows up and out, retract your scapulae',
                'single-arm-cable-curl' => 'Focus on squeezing your biceps',
                'single-arm-cable-row' => 'Pull your elbows down and in',
                'single-leg-leg-press' => 'Start with your weaker leg',
                'single-leg-lying-leg-curl' => 'Focus on squeezing your hamstrings',
                'standing-cable-hip-abduction' => 'Keep your torso upright, swing your leg out to the side',
                'standing-calf-raise' => 'Press up onto your toes',
