        'womens-foundations-5-day-body-part-split' => [
            'name_en' => 'Women\'s Foundations · 5-Day Body Part Split',
            'name_ru' => 'Женская базовая программа · 5 дней, сплит',
            'description_en' => '5 days a week, 8 weeks. Each day trains specific muscles: chest & triceps, glutes & quads, back & biceps, glutes & hamstrings, shoulders & abs — glutes get two dedicated days. Warm-up sets before the main lifts, moderate effort (RPE 6–9), two 4-week blocks.',
            'description_ru' => '5 дней в неделю, 8 недель. Каждый день — свои мышцы: грудь и трицепс, ягодицы и квадрицепсы, спина и бицепс, ягодицы и бицепс бедра, плечи и пресс — ягодицам отдано два отдельных дня. Разминочные подходы перед основными упражнениями, умеренное усилие (RPE 6–9), два блока по 4 недели.',
            'notes' => [
                'assisted-dip' => 'Keep your shoulder blades back and down',
                'assisted-pull-up' => 'Pull your elbows down towards your waist',
                'back-squat' => 'Sit down and back, keep your knees out',
                'barbell-curl' => 'Focus on squeezing your biceps',
                'barbell-hip-thrust' => 'Keep your rib cage and chin tucked',
                'bicycle-crunch' => 'Focus on flexing and rotating your spine',
                'cable-pull-through' => 'Focus on extending your hips',
                'cable-seated-row' => 'Pull your elbows down at your sides',
                'cable-tricep-kickback' => 'Rope. Keep your elbow behind your torso',
                'chest-supported-machine-row' => 'Pull your elbows up and out, squeeze your shoulder blades together',
                'crunch' => 'Flex your spine - don\'t yank your head',
                'deadlift' => 'Keep your hips high, lumbar spine neutral',
                'dumbbell-alternating-curl' => 'Focus on squeezing your biceps',
                'dumbbell-bench-press' => 'Keep your shoulder blades back and down',
                'dumbbell-front-raise' => 'Focus on squeezing your front delts',
                'dumbbell-lateral-raise' => 'Slightly internally rotate your shoulder',
                'dumbbell-row' => 'Pull your elbow down and back toward your hip',
                'dumbbell-walking-lunge' => '15 steps each leg. Keep your front shin vertical',
                'hanging-leg-raise' => 'Squeeze your glutes',
                'leg-extension' => 'Flex your quads',
                'machine-chest-press' => 'Keep your shoulder blades back and down',
                'machine-incline-chest-press' => 'Keep your shoulder blades back and down',
                'machine-seated-hip-abduction' => 'Flex your glutes',
                'military-press' => 'Squeeze your glutes to keep your torso upright',
                'plank' => 'Squeeze your glutes, flex your spine',
                'preacher-curl' => 'Squeeze your biceps',
