    /**
     * Idempotent: templates are matched by slug and updated in place (ids of weeks, days and
     * exercises are kept by position), so re-running never duplicates them and never detaches
     * users' cycles or workout history. Templates are never wiped: deleting one would cascade
     * to every user's cycle on it.
     */
    /** Russian version of a template note (database/seeders/data/notes_ru.php). */
    public static function notesRu(?string $en): ?string
    {
        static $ru = null;
        $ru ??= require __DIR__.'/data/notes_ru.php';

        return $en === null ? null : ($ru[$en] ?? null);
    }

    /** Every distinct exercise note used by the templates (for the translation check). */
    public static function allNotesEn(): array
    {
        $seeder = new self();
        $notes = [];
        foreach (self::TEMPLATES as $tpl) {
            if (! isset($tpl['weeks'])) {
                continue;
            }
            foreach ($seeder->explicitWeeks($tpl) as $w) {
                foreach ($w['days'] as $d) {
                    foreach ($d['exercises'] as $x) {
                        if ($x['notes_en'] !== null) {
                            $notes[$x['notes_en']] = true;
                        }
                    }
                }
            }
        }

        return array_keys($notes);
    }

    /** Number of ready-made programs (tests use it instead of a hard-coded count). */
    public static function count(): int
    {
        return count(self::TEMPLATES);
    }

    public function run(): void
    {
        $writer = app(ProgramWriter::class);
        $exerciseIds = Exercise::whereNull('user_id')->pluck('id', 'slug');

        foreach (self::TEMPLATES as $slug => $tpl) {
            $tree = [
                'slug' => $slug,
                'name_en' => $tpl['name_en'],
                'name_ru' => $tpl['name_ru'],
                'description_en' => $tpl['description_en'] ?? null,
                'description_ru' => $tpl['description_ru'] ?? null,
                'weeks' => array_map(fn ($w) => [
                    'block' => $w['block'],
                    'days' => array_map(fn ($d) => [
                        'title_en' => $d['title_en'],
                        'title_ru' => $d['title_ru'],
                        'exercises' => array_map(function ($x) use ($exerciseIds) {
                            $x['exercise_id'] = $exerciseIds[$x['exercise']]
                                ?? throw new \RuntimeException("Unknown exercise slug: {$x['exercise']}");
                            unset($x['exercise']);
                            $x['notes_ru'] ??= self::notesRu($x['notes_en'] ?? null);

                            return $x;
                        }, $d['exercises']),
                    ], $w['days']),
                ], isset($tpl['weeks']) ? $this->explicitWeeks($tpl) : $this->weeks($tpl['days'])),
            ];

            $program = Program::whereNull('user_id')->where('slug', $slug)->first()
                ?? new Program(['visibility' => 'public', 'source' => 'system']);

            if ($program->exists) {
                $this->attachExistingIds($program, $tree);
            }
            $writer->save($program, $tree, null);
        }
    }

    /** Give the new tree the ids of the existing weeks/days/exercises at the same positions. */
    private function attachExistingIds(Program $program, array &$tree): void
    {
        $weeks = $program->weeks()->with('days.exercises')->get()->values();
        foreach ($tree['weeks'] as $wi => &$w) {
            $week = $weeks[$wi] ?? null;
            if (! $week) {
                break;
            }
            $w['id'] = $week->id;
            foreach ($w['days'] as $di => &$d) {
                $day = $week->days->values()[$di] ?? null;
                if (! $day) {
                    break;
                }
                $d['id'] = $day->id;
                foreach ($d['exercises'] as $xi => &$x) {
                    $x['id'] = $day->exercises->values()[$xi]->id ?? null;
                }
            }
        }
    }

    private function explicitWeeks(array $tpl): array
    {
        $notes = $tpl['notes'] ?? [];

        return array_map(fn ($week, $wi) => [
            'week_no' => $wi + 1,
            'block' => $week[0],
            'days' => array_map(fn ($day, $di) => [
                'day_no' => $di + 1,
                'title_en' => $day[0],
                'title_ru' => $day[1],
                'exercises' => array_map(fn ($r) => [
                    'exercise' => $r[0],
                    'sets' => $r[1],
                    'reps' => $r[2],
                    'seconds' => $r[3],
                    'target_rpe' => $r[4],
                    'rest_min' => $r[5],
                    'rest_max' => $r[6],
                    'warmup_sets' => $r[7]['warmup_sets'] ?? null,
                    'load_pct' => $r[7]['load_pct'] ?? null,
                    'reps_max' => $r[7]['reps_max'] ?? null,
                    'reps_text' => $r[7]['reps_text'] ?? null,
                    'notes_en' => array_key_exists('notes_en', $r[7] ?? [])
                        ? $r[7]['notes_en']
                        : ($notes[$r[0]] ?? null),
                ], $day[2]),
            ], $week[1], array_keys($week[1])),
        ], $tpl['weeks'], array_keys($tpl['weeks']));
    }

    private function weeks(array $days): array
    {
        $weeks = [];
        foreach (range(1, 8) as $w) {
            $block2 = $w > 4;
            $weeks[] = [
                'week_no' => $w,
                'block' => $block2 ? 'intensity' : 'base',
                'days' => array_map(fn ($day, $i) => [
                    'day_no' => $i + 1,
                    'title_en' => $day[0],
                    'title_ru' => $day[1],
                    'exercises' => array_map(fn ($r) => [
                        'exercise' => $r[0],
                        'sets' => $r[1],
                        'reps' => $r[2] && $block2 && $r[7] ? $r[2] - 2 : $r[2],
                        'seconds' => $r[3] && $block2 ? $r[3] + 15 : $r[3],
                        'target_rpe' => $block2 ? min(9, $r[4] + 1) : $r[4],
                        'rest_min' => $r[5],
                        'rest_max' => $r[6],
                    ], $day[2]),
                ], $days, array_keys($days)),
            ];
        }

        return $weeks;
    }
}
